param([Parameter(Mandatory=$true)][string]$OutputDirectory)
$ErrorActionPreference='Stop';$ccRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../..'));$ccOut=[IO.Path]::GetFullPath($OutputDirectory);$ccName=Split-Path $ccOut -Leaf
if([IO.Path]::GetDirectoryName($ccOut)-ne(Join-Path $ccRoot 'reports/m4-crt-commandline-native')-or$ccName-notmatch'^[a-z0-9-]+$'){throw 'Private immediate fresh control report required'}
$ccBuilds=@{O0=(Join-Path $ccRoot "build/m4-cmd-controls-$ccName-O0");O2=(Join-Path $ccRoot "build/m4-cmd-controls-$ccName-O2")};foreach($ccP in @($ccOut)+@($ccBuilds.Values)){if(Test-Path -LiteralPath $ccP){throw 'Fresh report and every derived control build required'}}
function Get-CCHash([string]$p){(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}
$ccLLVM=Join-Path $ccRoot 'local/tools/llvm-21.1.8/clang+llvm-21.1.8-x86_64-pc-windows-msvc/bin';$ccVS='C:/Program Files/Microsoft Visual Studio/18/Community';$ccCMake=Join-Path $ccVS 'Common7/IDE/CommonExtensions/Microsoft/CMake/CMake/bin/cmake.exe';$ccResearch=Join-Path $ccRoot 'reports/m4-crt-commandline-native/static-r1';$ccNative=Join-Path $ccRoot 'reports/m4-crt-commandline-native/native-build-r3/build.json';$ccInputs=[ordered]@{};$ccInputs[$ccNative]=Get-CCHash $ccNative
foreach($ccPath in @($PSScriptRoot,(Join-Path $ccRoot 'tests/m4-crt-commandline-native'),$ccResearch)){foreach($ccF in Get-ChildItem -LiteralPath $ccPath -File -Recurse){$ccInputs[$ccF.FullName]=Get-CCHash $ccF.FullName}}
foreach($ccLevel in @('O0','O2')){$ccLibrary=Join-Path $ccRoot "build/m4-cmd-native-build-r3-$ccLevel/commandline_registry.lib";$ccInputs[$ccLibrary]=Get-CCHash $ccLibrary}
New-Item -ItemType Directory -Path $ccOut|Out-Null;foreach($ccPair in $ccInputs.GetEnumerator()){if($ccPair.Key-notmatch'\.lib$'){$ccCopy=Join-Path $ccOut ('sources/'+[IO.Path]::GetRelativePath($ccRoot,$ccPair.Key));New-Item -ItemType Directory -Force -Path (Split-Path $ccCopy -Parent)|Out-Null;Copy-Item -LiteralPath $ccPair.Key -Destination $ccCopy}}
$ccCommands=[Collections.Generic.List[object]]::new();$ccTools=[ordered]@{};$ccPass=$false
function Invoke-CCTool([string]$program,[string[]]$arguments,[string]$log){$ccTools[$program]=Get-CCHash $program;$ccLog=Join-Path $ccOut $log;[IO.File]::WriteAllBytes($ccLog,[byte[]]::new(0));&$program @arguments 2>&1|Tee-Object -FilePath $ccLog;$ccExit=$LASTEXITCODE;$ccCommands.Add([ordered]@{program=$program;arguments=$arguments;exit=$ccExit;log=$ccLog;log_sha256=(Get-CCHash $ccLog)});if($ccExit-ne0){throw 'Compiled command-line control failed'}}
try{Import-Module (Join-Path $ccVS 'Common7/Tools/Microsoft.VisualStudio.DevShell.dll');Enter-VsDevShell -VsInstallPath $ccVS -SkipAutomaticLocation -DevCmdArguments '-arch=x64 -host_arch=x64'|Out-Null
foreach($ccLevel in @('O0','O2')){$ccFlags=if($ccLevel-eq'O0'){'/Od /DNDEBUG'}else{'/O2 /DNDEBUG'};$ccLibrary=Join-Path $ccRoot "build/m4-cmd-native-build-r3-$ccLevel/commandline_registry.lib"
Invoke-CCTool $ccCMake @('-G','Ninja','-S',(Join-Path $PSScriptRoot 'controls'),'-B',$ccBuilds[$ccLevel],'-DCMAKE_BUILD_TYPE=Release',"-DCMAKE_CXX_COMPILER=$ccLLVM/clang-cl.exe","-DCMAKE_CXX_FLAGS_RELEASE=$ccFlags","-DMW34_CMD_INCLUDE=$ccResearch","-DMW34_CMD_LIBRARY=$ccLibrary") "configure-$ccLevel.log"
Invoke-CCTool $ccCMake @('--build',$ccBuilds[$ccLevel],'--verbose') "build-$ccLevel.log"
Invoke-CCTool (Join-Path $ccBuilds[$ccLevel] 'commandline_controls.exe') @((Join-Path $ccRoot 'MW3/Mech3.exe'),(Join-Path $ccRoot 'local/mw3-staged/Shared_DLLs/MSVCRT.DLL'),(Join-Path $ccResearch 'pack.bin')) "controls-$ccLevel.log"
Invoke-CCTool (Join-Path $ccBuilds[$ccLevel] 'commandline_publisher.exe') @((Join-Path $ccOut "publisher-$ccLevel")) "publisher-$ccLevel.log"
};$ccPass=$true}catch{$_|Out-String|Set-Content -LiteralPath (Join-Path $ccOut 'failure.txt');throw}finally{$ccArtifacts=[ordered]@{};foreach($ccP in @($ccOut)+@($ccBuilds.Values)){if(Test-Path -LiteralPath $ccP){foreach($ccF in Get-ChildItem -LiteralPath $ccP -File -Recurse){$ccArtifacts[$ccF.FullName]=Get-CCHash $ccF.FullName}}};[ordered]@{passed=$ccPass;inputs=$ccInputs;tools=$ccTools;commands=$ccCommands;artifacts=$ccArtifacts;scope='Actual compiled writer/query/ownership first-fault and partial cleanup controls only'}|ConvertTo-Json -Depth 12|Set-Content -LiteralPath (Join-Path $ccOut 'build.json')}
